def appliquer_remise(prix, taux=0.1):
    if prix <= 0:
        raise ValueError("prix invalide")
    return prix * (1 - taux)

print(appliquer_remise(100))
print(appliquer_remise(100, 0.2))

try:
    appliquer_remise(-5)
except ValueError as err:
    print("Erreur :", err)

phrase = "le chat et le chien et le chat"
compteur = {}

for mot in phrase.split():
    compteur[mot] = compteur.get(mot, 0) + 1

for mot, nombre in sorted(compteur.items()):
    print(f"{mot} : {nombre}")
